CREATE TEMPORARY VIEW dwd_search_be_log_${grass_region_without_quote} AS
SELECT
    request_id
    ,item_id
    ,CASE 
        WHEN edt_max IS NULL OR estimated_delivery_time_text = '' OR estimated_delivery_time_text IS NULL THEN ARRAY('no_edt_info','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours = 0 THEN ARRAY('0h','0d','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours = 1 THEN ARRAY('1h','0d','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours = 2 THEN ARRAY('2h','0d','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours = 3 THEN ARRAY('3h','0d','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours = 4 THEN ARRAY('4h','0d','__ALL__')
        WHEN edt_max = 0 AND edt_max_hours > 4 THEN ARRAY('>4h','0d','__ALL__')
        WHEN edt_max = 1 THEN ARRAY('1d','__ALL__')
        WHEN edt_max = 2 THEN ARRAY('2d','__ALL__')
        WHEN edt_max = 3 THEN ARRAY('3d','__ALL__')
        WHEN edt_max >= 4 and edt_max <= 7 THEN ARRAY('4-7d','__ALL__')
        WHEN edt_max > 7 THEN ARRAY('>7d','__ALL__')
        ELSE ARRAY('NULL','__ALL__')
    END AS edt_types
FROM
    srdi_mart.dwd_sr_data_warehouse_search_be_log
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW fp_edt_order_join_be_log_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,COALESCE(edt_types, ARRAY('NULL','__ALL__')) AS edt_types
    ,keyword_l1_category
    ,keyword_l1_category_id
    ,keyword_l2_category
    ,keyword_l2_category_id
    ,order_id
    ,a.item_id AS item_id
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv_usd) AS gmv_usd
    ,SUM(pc2_usd) AS pc2_usd
    ,SUM(edtmax_in_days) AS edt_numerator
    ,SUM(IF(edtmax_in_days IS NOT NULL, 1, 0)) AS edt_denominator
FROM
    dwd_fp_join_edt_order_${grass_region_without_quote} a
LEFT JOIN
    dwd_search_be_log_${grass_region_without_quote} b
ON
    a.request_id = b.request_id
    AND a.item_id = b.item_id
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW main_metrics_user_level_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,edt_types
    ,keyword_l1_category
    ,keyword_l1_category_id
    ,keyword_l2_category
    ,keyword_l2_category_id
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv_usd) AS gmv_usd
    ,SUM(pc2_usd) AS pc2_usd
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv_usd) / SUM(order_cnt) ELSE 0 END AS abs
    ,SUM(edt_numerator) AS edt_numerator
    ,SUM(edt_denominator) AS edt_denominator
FROM
    fp_edt_order_join_be_log_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW user_abs_${grass_region_without_quote} AS
SELECT
    user_id
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv_usd) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    main_metrics_user_level_grouped_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CACHE TABLE global_search_abs995_benchmark_${grass_region_without_quote} AS
SELECT
    APPROX_PERCENTILE(IF(abs > 0, abs, NULL), 0.995) as global_search_abs_995
FROM 
    user_abs_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_main_metrics_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    exp_group_id
    ,edt_type
    ,IF(keyword_l1_category IS NOT NULL, keyword_l1_category, '__ALL__') AS keyword_l1_category
    ,IF(keyword_l1_category_id IS NOT NULL, keyword_l1_category_id, '__ALL__') AS keyword_l1_category_id
    ,IF(keyword_l2_category IS NOT NULL, keyword_l2_category, '__ALL__') AS keyword_l2_category
    ,IF(keyword_l2_category_id IS NOT NULL, keyword_l2_category_id, '__ALL__') AS keyword_l2_category_id
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv_usd) AS gmv_usd
    ,SUM(IF(abs <= global_search_abs_995, gmv_usd, 0)) as gmv_usd_995
    ,SUM(IF(abs <= global_search_abs_995, gmv_usd, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= global_search_abs_995 THEN a.user_id END) AS gmv_uu_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_usd, 0)) AS pc2_gmv_usd_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_usd, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= global_search_abs_995 THEN a.user_id END) AS pc2_gmv_uu_995
    ,SUM(edt_numerator) / SUM(edt_denominator) AS avg_edt
FROM (
    SELECT
        *
        ,edt_type 
    FROM 
        main_metrics_user_level_grouped_${grass_region_without_quote}
        LATERAL VIEW EXPLODE(edt_types) AS edt_type
) a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
GROUP BY GROUPING SETS (
    (exp_group_id, edt_type, keyword_l1_category, keyword_l1_category_id, keyword_l2_category, keyword_l2_category_id)
    ,(exp_group_id, edt_type, keyword_l1_category, keyword_l1_category_id)
    ,(exp_group_id, edt_type)
);

--sql_divide_splitter--

