CREATE TEMPORARY VIEW gmv995_v2_item_order_level_${grass_region_without_quote} AS
SELECT
    user_id
    ,edt_types
    ,keyword_l1_category
    ,keyword_l1_category_id
    ,keyword_l2_category
    ,keyword_l2_category_id
    ,a.item_id AS item_id
    ,order_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,COALESCE(SUM(order_cnt), 0.0) AS order_cnt
    ,COALESCE(SUM(gmv_usd), 0.0) AS gmv
    ,COALESCE(SUM(pc2_usd), 0.0) AS pc2_gmv
FROM
    fp_edt_order_join_be_log_${grass_region_without_quote} a
LEFT JOIN
    srdi_mart.dim_sr_data_warehouse_item b
ON
    a.item_id = b.item_id
    AND b.grass_region = ${grass_region}
    AND b.local_date = ${local_date}
GROUP BY
    1,2,3,4,5,6,7,8,9;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_user_level_filtered_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(b) */
    user_id
    ,edt_type
    ,IF(keyword_l1_category IS NOT NULL, keyword_l1_category, '__ALL__') AS keyword_l1_category
    ,IF(keyword_l1_category_id IS NOT NULL, keyword_l1_category_id, '__ALL__') AS keyword_l1_category_id
    ,IF(keyword_l2_category IS NOT NULL, keyword_l2_category, '__ALL__') AS keyword_l2_category
    ,IF(keyword_l2_category_id IS NOT NULL, keyword_l2_category_id, '__ALL__') AS keyword_l2_category_id
    ,a.category_tag AS category_tag
    ,SUM(IF(gmv <= gmv_995pct, order_cnt, 0)) AS gmv_order_cnt_995_v2
    ,SUM(IF(gmv <= gmv_995pct, gmv, gmv_995pct)) AS gmv_995_v2
    ,SUM(IF(pc2_gmv <= pc2_gmv_995pct, pc2_gmv, pc2_gmv_995pct)) AS pc2_gmv_995_v2
FROM (
    SELECT
        *
        ,edt_type 
    FROM 
        gmv995_v2_item_order_level_${grass_region_without_quote}
        LATERAL VIEW EXPLODE(edt_types) AS edt_type
) a
JOIN
    gmv995_v2_outlier_${grass_region_without_quote} b
ON
    a.category_tag = b.category_tag
GROUP BY GROUPING SETS (
     (user_id, edt_type, keyword_l1_category, keyword_l1_category_id, keyword_l2_category, keyword_l2_category_id, a.category_tag)
    ,(user_id, edt_type, keyword_l1_category, keyword_l1_category_id, a.category_tag)
    ,(user_id, edt_type, a.category_tag)
);

--sql_divide_splitter--

