CREATE TEMPORARY VIEW dwd_ads_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,COALESCE(keyword_l1_category, '') AS keyword_l1_category
    ,COALESCE(keyword_l1_category_id, '') AS keyword_l1_category_id
    ,COALESCE(keyword_l2_category, '') AS keyword_l2_category
    ,COALESCE(keyword_l2_category_id, '') AS keyword_l2_category_id
    ,COALESCE(edt_types, ARRAY('NULL','__ALL__')) AS edt_types
    ,expenditure_amt_usd
FROM
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
LEFT JOIN
    dwd_fp_dims_for_ads_join_${grass_region_without_quote} b
ON
    a.raw_request_id = b.request_id
    AND a.item_id = b.item_id
LEFT JOIN
    dwd_search_be_log_${grass_region_without_quote} c
ON
    a.raw_request_id = c.request_id
    AND a.item_id = c.item_id
WHERE
    a.grass_date = ${local_date}
    AND a.grass_region = ${grass_region}
    AND a.tz_type = 'local'
    AND a.entrance = 1
    AND a.user_id > 0;

