CREATE TEMPORARY VIEW dws_ads_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,edt_type
    ,IF(keyword_l1_category IS NOT NULL, keyword_l1_category, '__ALL__') AS keyword_l1_category
    ,IF(keyword_l1_category_id IS NOT NULL, keyword_l1_category_id, '__ALL__') AS keyword_l1_category_id
    ,IF(keyword_l2_category IS NOT NULL, keyword_l2_category, '__ALL__') AS keyword_l2_category
    ,IF(keyword_l2_category_id IS NOT NULL, keyword_l2_category_id, '__ALL__') AS keyword_l2_category_id
    ,SUM(expenditure_amt_usd) AS expenditure_amt_usd
FROM (
    SELECT
        *
        ,edt_type 
    FROM 
        dwd_ads_${grass_region_without_quote}
        LATERAL VIEW EXPLODE(edt_types) AS edt_type
) a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY GROUPING SETS (
    (exp_group_id, edt_type, keyword_l1_category, keyword_l1_category_id, keyword_l2_category, keyword_l2_category_id)
    ,(exp_group_id, edt_type, keyword_l1_category, keyword_l1_category_id)
    ,(exp_group_id, edt_type)
);

