INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_edt_keyword_category_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
/*+ BROADCASTJOIN(b) */
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,a.edt_type
    ,a.keyword_l1_category
    ,a.keyword_l1_category_id
    ,a.keyword_l2_category
    ,a.keyword_l2_category_id
    ,search_uu
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv_usd AS gmv
    ,gmv_usd_995 AS gmv_995 
    ,gmv_uu_995
    ,pc2_gmv_usd_995 AS pc2_gmv_995
    ,pc2_gmv_uu_995
    ,expenditure_amt_usd AS ads_revenue
    ,avg_edt
    ,high_gmv_order_cnt_995_v2
    ,high_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_gmv_order_cnt_995_v2
    ,low_gmv_995_v2
    ,low_pc2_gmv_995_v2
FROM
    dws_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    dim_exp_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
LEFT JOIN
    dws_search_uu_metric_${grass_region_without_quote} c
ON
    a.exp_group_id = c.exp_group_id
    AND a.edt_type = '__ALL__'
    AND a.keyword_l1_category = c.keyword_l1_category
    AND a.keyword_l1_category_id = c.keyword_l1_category_id
    AND a.keyword_l2_category = c.keyword_l2_category
    AND a.keyword_l2_category_id = c.keyword_l2_category_id
LEFT JOIN
    dws_ads_${grass_region_without_quote} d
ON
    a.exp_group_id = d.exp_group_id
    AND a.edt_type = d.edt_type
    AND a.keyword_l1_category = d.keyword_l1_category
    AND a.keyword_l1_category_id = d.keyword_l1_category_id
    AND a.keyword_l2_category = d.keyword_l2_category
    AND a.keyword_l2_category_id = d.keyword_l2_category_id
LEFT JOIN
    gmv995_v2_exp_metrics_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.edt_type = e.edt_type
    AND a.keyword_l1_category = e.keyword_l1_category
    AND a.keyword_l1_category_id = e.keyword_l1_category_id
    AND a.keyword_l2_category = e.keyword_l2_category
    AND a.keyword_l2_category_id = e.keyword_l2_category_id;
